import numpy as np, itertools
L=open('opt3.xyz').read().split('\n')
n=int(L[0]); els=[];pos=[]
for l in L[2:2+n]:
    p=l.split(); els.append(p[0]); pos.append([float(x) for x in p[1:4]])
pos=np.array(pos)
def d(i,j): return round(float(np.linalg.norm(pos[i]-pos[j])),3)
print('Ru-N1',d(0,1),'Ru-CL',d(0,13),'Ru-CR',d(0,20),'Ru-H',d(0,26),'Ru-COax',d(0,27),'Ru-COeq',d(0,29))
names={1:'Npy',13:'CL',20:'CR',26:'H',27:'COax',29:'COeq'}
for a,b in itertools.combinations(names,2):
    v1=pos[a]-pos[0]; v2=pos[b]-pos[0]
    print(names[a],names[b],round(float(np.degrees(np.arccos(v1.dot(v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))),1))
print('C27-O28',d(27,28),'C29-O30',d(29,30))
print('C2-C7(exo)',d(2,10),'N1-C2',d(1,2))
# connectivity sanity
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Ru':1.46}
bonds={i:[] for i in range(n)}
for i in range(n):
  for j in range(i+1,n):
    if np.linalg.norm(pos[i]-pos[j])<1.25*(cov[els[i]]+cov[els[j]]):
      bonds[i].append(j); bonds[j].append(i)
for i in range(n):
    print(i,els[i],len(bonds[i]),[els[k] for k in bonds[i]])
